// Photo asset "folding-chair" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/folding-chair.js"></script>
//   <img data-asset="folding-chair" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "folding-chair": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="folding-chair"]').forEach(function (img) { img.src = window.ASSETS["folding-chair"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
